insert into public.feelings
  (slug, category, title, teaser, corpo_question, corpo_text, mente_question, mente_text, espirito_question, espirito_text, verse_text, verse_reference, acao_question, acao_text, sort_order)
values
('ansiedade', 'ansiedade_medo', 'Ansiedade', 'Talvez sua mente esteja vivendo amanhã enquanto seu corpo ainda está tentando sobreviver a hoje.', 'O que está acontecendo no seu corpo?', 'Diante de uma ameaça — real ou imaginada — o corpo acelera. Coração mais rápido, respiração curta, músculos tensos, digestão em segundo plano. É um sistema antigo, feito para durar minutos. O problema não é ele existir: é ele ficar ligado por semanas.', 'O que está acontecendo dentro de você?', 'A ansiedade se alimenta de cenários. A mente ensaia o pior para tentar controlá-lo antes que aconteça. Ensaiar dá uma sensação momentânea de preparo, e por isso o cérebro repete. Você não está fraco: está repetindo um hábito mental que já teve utilidade.', 'Existe outra forma de olhar para isso.', 'Jesus fala sobre ansiedade sem repreender quem sente. Ele aponta para uma questão prática: preocupar-se não acrescenta nada ao que virá. O convite não é fingir calma, é devolver o amanhã para quem já está lá. Cuidar do hoje é um ato de fé, não de descuido.', 'Portanto, não se preocupem com o amanhã, pois o amanhã se preocupará consigo mesmo. Basta a cada dia o seu próprio mal.', 'Mateus 6.34', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Durante os próximos 10 minutos, escreva tudo aquilo que você está tentando controlar e que não depende de você. Depois escolha apenas uma coisa que realmente está nas suas mãos. Faça essa coisa hoje.', 0),
('medo', 'ansiedade_medo', 'Medo', 'O medo raramente mente sobre o risco. Ele mente sobre o seu tamanho diante dele.', 'O que está acontecendo no seu corpo?', 'O medo é uma resposta rápida: adrenalina, atenção estreitada, corpo pronto para reagir. Ele existe para te manter vivo. Fora do perigo real, essa mesma resposta vira paralisia.', 'O que está acontecendo dentro de você?', 'A mente confunde possibilidade com probabilidade. Aquilo que pode acontecer passa a ser tratado como aquilo que vai acontecer. Evitar alivia por instantes e ensina ao cérebro que aquilo era mesmo perigoso.', 'Existe outra forma de olhar para isso.', 'A frase «não temas» aparece na Bíblia quase sempre acompanhada de um motivo, e o motivo nunca é «porque não há perigo». É «porque eu estou contigo». A coragem cristã não nega o risco: ela muda quem caminha junto.', 'Não tema, pois estou com você; não tenha medo, pois eu sou o seu Deus.', 'Isaías 41.10', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escreva o medo em uma frase concreta. Depois, dê hoje o menor passo possível na direção dele — pequeno o suficiente para você conseguir, grande o suficiente para doer um pouco.', 1),
('angustia', 'ansiedade_medo', 'Angústia', 'Angústia é o corpo pedindo uma saída que a mente ainda não encontrou.', 'O que está acontecendo no seu corpo?', 'Aperto no peito, respiração presa, um nó que não tem endereço. A angústia costuma ser difusa: você sente antes de saber o que é.', 'O que está acontecendo dentro de você?', 'Diferente do medo, ela não tem alvo claro. Por isso a mente procura desesperadamente um nome. Nomear o que se sente reduz a intensidade — não porque resolve, mas porque devolve a sensação ao tamanho real.', 'Existe outra forma de olhar para isso.', 'Os Salmos são cheios de angústia dita em voz alta. A tradição bíblica não pede que você chegue calmo diante de Deus. Pede que você chegue. O lamento é uma forma de oração, não uma falha nela.', 'Na minha angústia clamei ao Senhor, e ele me respondeu.', 'Salmo 120.1', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Por 10 minutos, escreva sem parar e sem editar tudo o que está apertado. No fim, sublinhe uma única frase — a mais verdadeira. Leia em voz alta uma vez.', 2),
('preocupacao', 'ansiedade_medo', 'Preocupação', 'Você está pagando hoje por um problema que talvez nunca chegue.', 'O que está acontecendo no seu corpo?', 'A preocupação crônica mantém um nível baixo e constante de alerta. Sono mais raso, mandíbula tensa, cansaço sem esforço físico.', 'O que está acontecendo dentro de você?', 'Existe uma crença silenciosa por trás: «se eu me preocupar, eu me protejo». A mente trata a preocupação como trabalho. Mas trabalho produz resultado; preocupação produz repetição.', 'Existe outra forma de olhar para isso.', 'Paulo escreve sobre isso de dentro de uma prisão. Ele não propõe otimismo, propõe transferência: entregar em oração aquilo que você não consegue soltar sozinho.', 'Não andem ansiosos por coisa alguma, mas em tudo... apresentem seus pedidos a Deus.', 'Filipenses 4.6', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escolha um horário fixo hoje, de 15 minutos, para se preocupar. Fora dele, anote a preocupação numa lista e volte ao que estava fazendo.', 3),
('confusao', 'ansiedade_medo', 'Confusão', 'Talvez você não esteja perdido. Talvez esteja com informação demais e silêncio de menos.', 'O que está acontecendo no seu corpo?', 'Excesso de estímulo satura a atenção. O corpo responde com cansaço mental, leitura difícil, decisões adiadas.', 'O que está acontecendo dentro de você?', 'Confusão quase sempre é conflito entre duas coisas que você quer e não pode ter ao mesmo tempo. Enquanto você não nomear o conflito, vai tentar resolvê-lo com mais informação — e a informação só aumenta o ruído.', 'Existe outra forma de olhar para isso.', 'A sabedoria bíblica não é um mapa completo entregue de uma vez. É luz para o próximo passo. Isso é frustrante para quem quer garantias, e libertador para quem só precisa andar.', 'Lâmpada para os meus pés é a tua palavra, e luz para o meu caminho.', 'Salmo 119.105', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Fique 10 minutos sem tela, sem música, sem ninguém. Depois escreva as duas coisas que estão em conflito. Só isso.', 4),
('tristeza', 'perdas', 'Tristeza', 'Nem tudo que dói precisa ser resolvido hoje. Algumas coisas precisam ser sentidas primeiro.', 'O que está acontecendo no seu corpo?', 'A tristeza desacelera. Menos energia, movimentos mais lentos, vontade de recolher. É um estado de conservação, não um defeito.', 'O que está acontecendo dentro de você?', 'Ela costuma sinalizar perda: de algo, de alguém, de uma versão sua. A mente revisita cenas tentando entender. Quando você tenta apenas se distrair, a tristeza não vai embora — ela só espera.', 'Existe outra forma de olhar para isso.', 'A Bíblia tem um livro inteiro chamado Lamentações. Deus não pede que você maquie a dor. Há espaço para chorar sem que isso signifique falta de fé.', 'Perto está o Senhor dos que têm o coração quebrantado.', 'Salmo 34.18', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Reserve 15 minutos hoje só para a tristeza, sem celular. Depois faça uma coisa pequena e concreta: um banho, uma caminhada, uma refeição de verdade.', 5),
('luto', 'perdas', 'Luto', 'Luto não é um problema a ser resolvido. É um amor que não tem mais onde pousar.', 'O que está acontecendo no seu corpo?', 'O luto afeta sono, apetite, memória e imunidade. Ondas de dor aparecem sem aviso, disparadas por cheiros, músicas, lugares.', 'O que está acontecendo dentro de você?', 'Não existe uma sequência correta de etapas. O luto vai e volta. Querer «superar» rápido costuma prolongar. O que muda com o tempo não é o tamanho da falta: é o tamanho da vida ao redor dela.', 'Existe outra forma de olhar para isso.', 'Jesus chorou diante do túmulo de um amigo, sabendo o que faria em seguida. Isso diz algo definitivo: a esperança não cancela a dor. As duas cabem juntas.', 'Jesus chorou.', 'João 11.35', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escreva uma carta para quem partiu. Não precisa mostrar a ninguém. Conte uma coisa que você nunca disse.', 6),
('solidao', 'perdas', 'Solidão', 'Você pode estar cercado de gente e mesmo assim não estar sendo visto por ninguém.', 'O que está acontecendo no seu corpo?', 'A solidão prolongada mantém o corpo em alerta leve: sono pior, mais inflamação, menos energia. Somos animais que regulam o próprio sistema na presença de outros.', 'O que está acontecendo dentro de você?', 'Ela distorce a leitura social: você passa a interpretar silêncio como rejeição e evita se aproximar, o que aumenta o isolamento. É um ciclo, não um destino.', 'Existe outra forma de olhar para isso.', 'A primeira coisa que Deus chama de «não bom» na Bíblia é o ser humano estar só. A vida cristã é comunitária por desenho, não por conveniência.', 'Não é bom que o homem esteja só.', 'Gênesis 2.18', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Mande hoje uma mensagem específica para uma pessoa: não «oi, sumido», mas «lembrei de você por causa disso». Especificidade cria vínculo.', 7),
('abandono', 'perdas', 'Abandono', 'Quem foi embora escreveu uma frase sobre si. Você é que transformou em frase sobre você.', 'O que está acontecendo no seu corpo?', 'Experiências de abandono deixam o sistema de apego em alerta: reações intensas a distanciamentos pequenos, sensação física de queda.', 'O que está acontecendo dentro de você?', 'A mente cria uma regra: «vão embora de novo». Essa regra faz você antecipar a perda — controlando, testando, se afastando antes. E frequentemente produz o que temia.', 'Existe outra forma de olhar para isso.', 'A promessa bíblica não é que ninguém vai te deixar. É que existe uma presença que não depende do comportamento humano. Isso não substitui vínculos: sustenta você enquanto eles se refazem.', 'Ainda que meu pai e minha mãe me abandonem, o Senhor me acolherá.', 'Salmo 27.10', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escreva a regra que você criou («todo mundo vai embora»). Depois escreva três nomes que contradizem essa regra. Fale com um deles hoje.', 8),
('rejeicao', 'perdas', 'Rejeição', 'Um não sobre uma parte de você virou um não sobre você inteiro.', 'O que está acontecendo no seu corpo?', 'A dor social ativa regiões cerebrais parecidas com as da dor física. Não é exagero seu: rejeição dói de verdade.', 'O que está acontecendo dentro de você?', 'A mente generaliza. Um não vira «eu nunca». O antídoto não é autoestima inflada, é precisão: dizer exatamente o que foi recusado, por quem, e em que contexto.', 'Existe outra forma de olhar para isso.', 'Jesus foi rejeitado publicamente, e isso não alterou quem ele era. O valor de uma pessoa, na visão cristã, não é atribuído por consenso.', 'Foi desprezado e rejeitado pelos homens.', 'Isaías 53.3', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escreva a rejeição em uma frase precisa, com nome e contexto. Leia. Perceba o quanto ela é menor do que a frase que você vinha repetindo.', 9),
('desanimo', 'perdas', 'Desânimo', 'Você não perdeu a vontade. Você perdeu a sensação de que adianta.', 'O que está acontecendo no seu corpo?', 'Sono irregular, pouco movimento e alimentação instável reduzem a disposição de forma mensurável. Às vezes o desânimo começa no corpo, não na alma.', 'O que está acontecendo dentro de você?', 'Ele nasce da distância entre esforço e resultado visível. Quando o retorno demora, o cérebro corta o investimento. Metas menores restauram o sinal de progresso.', 'Existe outra forma de olhar para isso.', 'A Bíblia fala em «não se cansar de fazer o bem» reconhecendo que cansar é o normal. O foco muda de intensidade para constância.', 'Não nos cansemos de fazer o bem, pois no tempo próprio colheremos.', 'Gálatas 6.9', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escolha a menor versão possível de algo importante que você parou de fazer. Faça hoje essa versão mínima. Só ela.', 10),
('desesperanca', 'perdas', 'Desesperança', 'Talvez você não tenha desistido do futuro. Talvez só tenha parado de conseguir imaginá-lo.', 'O que está acontecendo no seu corpo?', 'Estados prolongados de desesperança afetam sono, energia e concentração. O corpo entra em economia.', 'O que está acontecendo dentro de você?', 'A mente projeta o presente para sempre: «isso nunca vai mudar». É uma previsão, não um fato — e previsões feitas em estado de exaustão são péssimas.', 'Existe outra forma de olhar para isso.', 'A esperança cristã não é otimismo sobre circunstâncias. É confiança em alguém que permanece quando as circunstâncias não mudam no prazo que queremos.', 'Por que você está assim tão triste, ó minha alma? Ponha a sua esperança em Deus!', 'Salmo 42.11', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escreva uma frase começando com «se as coisas melhorarem um pouco, eu gostaria de...». Depois conte isso para alguém hoje.', 11),
('vazio', 'perdas', 'Vazio', 'Tem coisa que preenche o tempo e mesmo assim deixa o dia oco.', 'O que está acontecendo no seu corpo?', 'Excesso de estímulo rápido (rolagem, notificações, consumo) dessensibiliza a resposta de recompensa. Depois, o que é lento parece insuportavelmente sem graça.', 'O que está acontecendo dentro de você?', 'O vazio costuma indicar falta de sentido, não falta de atividade. Pessoas ocupadíssimas sentem vazio todos os dias.', 'Existe outra forma de olhar para isso.', 'Agostinho descreveu isso como uma inquietação que só encontra descanso em Deus. A ideia cristã é que fomos feitos para algo maior do que consumo.', 'Todos os rios vão para o mar, contudo o mar nunca se enche.', 'Eclesiastes 1.7', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Passe 30 minutos hoje fazendo algo que não gera nada: sem produzir, sem postar, sem registrar. Só viver aquilo.', 12),
('raiva', 'relacoes', 'Raiva', 'A raiva quase sempre está protegendo alguma coisa mais frágil embaixo dela.', 'O que está acontecendo no seu corpo?', 'Adrenalina, calor, tensão muscular, foco estreito. O corpo fica pronto para lutar em segundos e leva de 20 a 30 minutos para voltar ao normal.', 'O que está acontecendo dentro de você?', 'A raiva sinaliza limite violado ou injustiça percebida. O problema raramente é senti-la: é agir dentro dos primeiros minutos, quando o julgamento está pior.', 'Existe outra forma de olhar para isso.', 'A Bíblia não proíbe a raiva. Ela põe um prazo e um limite: não deixe que ela se torne pecado, nem que durma com você.', 'Irem-se, mas não pequem. Não permitam que o sol se ponha estando vocês ainda irados.', 'Efésios 4.26', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Da próxima vez que a raiva subir, espere 20 minutos antes de responder. Nesse intervalo escreva o que foi violado — não o que você quer dizer.', 13),
('rancor', 'relacoes', 'Rancor', 'Você está guardando uma conta que a outra pessoa nem sabe que existe.', 'O que está acontecendo no seu corpo?', 'Reviver a ofensa reativa a resposta de estresse. Você paga fisiologicamente por algo que já acabou.', 'O que está acontecendo dentro de você?', 'O rancor promete justiça e entrega repetição. A mente ensaia o confronto que nunca acontece, mantendo a ferida aberta.', 'Existe outra forma de olhar para isso.', 'Perdoar, no sentido bíblico, não é dizer que não teve importância. É desistir de cobrar pessoalmente uma dívida — e confiar que a justiça não depende só de você.', 'Suportem-se uns aos outros e perdoem as queixas que tiverem uns contra os outros.', 'Colossenses 3.13', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escreva a dívida que você está cobrando. Depois escreva o preço que você tem pago para continuar cobrando. Compare.', 14),
('odio', 'relacoes', 'Ódio', 'O ódio ocupa espaço na sua vida como se fosse aluguel — e quem cobra não é você.', 'O que está acontecendo no seu corpo?', 'É um estado de ativação sustentada. Afeta sono, concentração e humor mesmo longe da pessoa envolvida.', 'O que está acontecendo dentro de você?', 'O ódio simplifica: transforma alguém em uma única coisa. Essa simplificação é confortável e falsa, e mantém você preso à história.', 'Existe outra forma de olhar para isso.', 'O ensino de Jesus sobre amar inimigos não é ingenuidade moral. É estratégia de libertação: enquanto você odeia, o outro continua governando sua vida interior.', 'Amem os seus inimigos e orem por aqueles que os perseguem.', 'Mateus 5.44', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escreva uma frase verdadeira e humana sobre essa pessoa que não seja sobre o que ela te fez. Só uma.', 15),
('inveja', 'relacoes', 'Inveja', 'A inveja é uma bússola torta: aponta para o que você quer, usando a vida de outro como mapa.', 'O que está acontecendo no seu corpo?', 'Comparação constante ativa estresse leve e contínuo, sobretudo em ambientes de exposição digital.', 'O que está acontecendo dentro de você?', 'Você compara o seu bastidor com o palco alheio. A inveja carrega informação útil — o que você deseja — misturada a uma mentira: que o sucesso do outro reduz o seu espaço.', 'Existe outra forma de olhar para isso.', 'A tradição bíblica trata a inveja como corrosão interna: ela apodrece quem sente, não quem é invejado.', 'O coração em paz dá vida ao corpo, mas a inveja apodrece os ossos.', 'Provérbios 14.30', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escreva o nome de quem você inveja e, ao lado, o que exatamente você quer. Depois escreva o primeiro passo real para você buscar isso.', 16),
('ciume', 'relacoes', 'Ciúme', 'Talvez não seja desconfiança do outro. Talvez seja medo de não ser suficiente.', 'O que está acontecendo no seu corpo?', 'Picos de alerta, insônia, checagens compulsivas. O corpo responde como se houvesse ameaça iminente.', 'O que está acontecendo dentro de você?', 'O ciúme se alimenta de interpretação, não de evidência. Controlar traz alívio momentâneo e aumenta a insegurança no médio prazo.', 'Existe outra forma de olhar para isso.', 'O amor descrito por Paulo tem uma característica difícil: confia. Confiança não é ingenuidade — é escolha de não viver como refém da suspeita.', 'O amor... tudo crê, tudo espera, tudo suporta.', '1 Coríntios 13.7', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Hoje, em vez de verificar, converse. Diga: «tenho sentido isso» — sem acusação, sem interrogatório.', 17),
('ressentimento', 'relacoes', 'Ressentimento', 'Ressentimento é dor antiga que aprendeu a se disfarçar de opinião.', 'O que está acontecendo no seu corpo?', 'A memória emocional reativa o corpo: um assunto antigo muda sua postura e sua respiração hoje.', 'O que está acontecendo dentro de você?', 'Ele se instala quando algo não foi dito. A mente reescreve o episódio infinitas vezes, sempre com você calado. Falar — mesmo tarde — quebra o loop.', 'Existe outra forma de olhar para isso.', 'A Bíblia orienta a resolver antes que a raiz cresça. Não por delicadeza, mas porque raiz amarga contamina o que está ao redor.', 'Cuidem para que ninguém... deixe que alguma raiz de amargura brote e cause perturbação.', 'Hebreus 12.15', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escreva o que você não disse na época. Decida hoje uma de duas coisas: dizer, ou encerrar por escrito e não voltar mais ao assunto sozinho.', 18),
('falta-de-perdao', 'relacoes', 'Falta de perdão', 'Você não perdoa porque teme que perdoar seja o mesmo que dizer que foi tudo bem.', 'O que está acontecendo no seu corpo?', 'Guardar ofensas mantém ativação crônica: pressão, sono, disposição — tudo sente.', 'O que está acontecendo dentro de você?', 'Perdão não é reconciliação, não é esquecer e não é obrigar-se a conviver. É soltar o direito de cobrar. Podem existir limites, distância e consequências.', 'Existe outra forma de olhar para isso.', 'Jesus liga perdão recebido a perdão concedido. Não como troca, mas como coerência: quem sabe o que é ser perdoado tem outra relação com dívidas alheias.', 'Perdoa as nossas dívidas, assim como perdoamos aos nossos devedores.', 'Mateus 6.12', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Diga em voz alta, sozinho: «eu abro mão de cobrar isso». Se ainda não conseguir, diga: «eu quero conseguir um dia». Isso também conta.', 19),
('comparacao', 'relacoes', 'Comparação', 'Você está correndo uma prova em que ninguém combinou a mesma linha de largada.', 'O que está acontecendo no seu corpo?', 'Rolagem infinita mantém pequenos picos de dopamina e comparação. Sensação: cansaço sem esforço.', 'O que está acontecendo dentro de você?', 'Comparação é automática. O que dá para escolher é a amostra: você decide a quem se expõe e com que frequência.', 'Existe outra forma de olhar para isso.', 'Paulo escreve que quem se mede por si mesmo perde a noção de tudo. A medida cristã é vocação, não ranking.', 'Cada um examine o seu próprio procedimento... sem se comparar com ninguém.', 'Gálatas 6.4', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Silencie hoje três contas que te fazem se sentir atrasado. Não é fuga: é escolher a amostra.', 20),
('frustracao', 'proposito_acao', 'Frustração', 'A distância entre o que você esperava e o que aconteceu tem um nome — e não é fracasso.', 'O que está acontecendo no seu corpo?', 'A quebra de expectativa produz queda abrupta de dopamina: irritação, cansaço, vontade de largar tudo.', 'O que está acontecendo dentro de você?', 'Frustração é sinal de investimento. Ela dói na proporção do que importava. A pergunta útil não é «por que comigo», é «o que dependia de mim aqui».', 'Existe outra forma de olhar para isso.', 'A Bíblia trata planos humanos com realismo: você planeja, mas não controla o desfecho. Isso não é fatalismo — é humildade operacional.', 'Em seu coração o homem planeja o seu caminho, mas o Senhor determina os seus passos.', 'Provérbios 16.9', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Separe em duas colunas: o que dependia de você, o que não dependia. Refaça só a primeira coluna.', 21),
('falta-de-proposito', 'proposito_acao', 'Falta de propósito', 'Talvez você não precise descobrir o propósito da sua vida. Talvez precise do propósito desta semana.', 'O que está acontecendo no seu corpo?', 'Rotinas sem sentido reduzem engajamento e energia. O corpo responde à ausência de direção com apatia.', 'O que está acontecendo dentro de você?', 'Propósito raramente chega como revelação. Ele aparece na interseção entre o que você faz bem, o que te move e o que alguém precisa.', 'Existe outra forma de olhar para isso.', 'Na visão cristã, propósito não é algo que você inventa sozinho: é algo que se descobre servindo. Começa pequeno, quase sempre perto.', 'Cada um exerça o dom que recebeu para servir os outros.', '1 Pedro 4.10', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escreva uma coisa que você faz bem e uma pessoa que precisa disso essa semana. Ofereça hoje.', 22),
('procrastinacao', 'proposito_acao', 'Procrastinação', 'Você não está com preguiça. Você está evitando um desconforto que ainda não nomeou.', 'O que está acontecendo no seu corpo?', 'Adiar reduz o desconforto na hora — e ensina o cérebro a repetir. O alívio imediato é o combustível do ciclo.', 'O que está acontecendo dentro de você?', 'Procrastinação é regulação de emoção, não gestão de tempo. Por trás costuma haver medo de fazer mal feito, tédio ou ausência de clareza sobre o primeiro passo.', 'Existe outra forma de olhar para isso.', 'A sabedoria bíblica valoriza começos pequenos e constância acima de grandes intenções. Fidelidade no pouco é um princípio, não um consolo.', 'Quem observa o vento não semeará; quem olha as nuvens não colherá.', 'Eclesiastes 11.4', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Trabalhe 10 minutos na tarefa que você está adiando. Cronômetro ligado. Depois disso pode parar — se ainda quiser.', 23),
('preguica', 'proposito_acao', 'Preguiça', 'Antes de se acusar, pergunte: é falta de vontade ou é falta de descanso de verdade?', 'O que está acontecendo no seu corpo?', 'Sono ruim, sedentarismo e alimentação instável derrubam a disposição. Muita «preguiça» é exaustão mal diagnosticada.', 'O que está acontecendo dentro de você?', 'Quando a tarefa é vaga, o cérebro trava. Definir a próxima ação física concreta («abrir o documento») costuma resolver mais do que motivação.', 'Existe outra forma de olhar para isso.', 'A Bíblia elogia o trabalho e institui o descanso. As duas coisas. Descanso programado não é preguiça; preguiça é fuga contínua sem descanso real.', 'Vá observar a formiga... ela não tem chefe, e ainda assim prepara o seu alimento.', 'Provérbios 6.6-8', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escreva a próxima ação física em cinco palavras. Faça agora. Depois durma cedo hoje.', 24),
('impaciencia', 'proposito_acao', 'Impaciência', 'Você quer a colheita no calendário da semeadura.', 'O que está acontecendo no seu corpo?', 'Vivemos em ambientes de resposta instantânea. A tolerância à espera diminui e o corpo reage à demora como se fosse ameaça.', 'O que está acontecendo dentro de você?', 'A impaciência distorce prazos: processos longos passam a parecer fracassos. Marcar progresso intermediário devolve a noção real de avanço.', 'Existe outra forma de olhar para isso.', 'A paciência aparece na Bíblia como fruto — algo que cresce com tempo e cuidado, não como decisão instantânea.', 'O fruto do Espírito é amor, alegria, paz, paciência...', 'Gálatas 5.22', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escolha algo que você quer acelerar. Escreva o prazo realista. Depois marque no calendário só o próximo passo.', 25),
('dificuldade-de-recomecar', 'proposito_acao', 'Dificuldade de recomeçar', 'Recomeçar parece caro porque você está tentando voltar ao ponto em que parou — e não ao próximo passo.', 'O que está acontecendo no seu corpo?', 'Interromper um hábito quebra o automatismo. O reinício exige mais energia consciente — isso é neurologia, não caráter.', 'O que está acontecendo dentro de você?', 'A mente exige que o recomeço seja perfeito e completo. Essa exigência é o que impede o retorno. Recomeço bom é pequeno e imediato.', 'Existe outra forma de olhar para isso.', 'A misericórdia bíblica se renova a cada manhã. O cristianismo é, em grande medida, uma religião de recomeços.', 'As misericórdias do Senhor... se renovam a cada manhã.', 'Lamentações 3.22-23', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Recomece hoje na versão mais ridícula possível: cinco minutos, uma página, uma quadra. Só volte a estar em movimento.', 26),
('tentacao', 'proposito_acao', 'Tentação', 'A decisão difícil raramente é no momento. É antes dele.', 'O que está acontecendo no seu corpo?', 'O desejo tem curva: sobe, atinge o pico e cai. Quem atravessa a onda sem agir aprende que ela passa mesmo sem ser obedecida.', 'O que está acontecendo dentro de você?', 'Contexto vence força de vontade. Mudar ambiente, horário e acesso é mais eficaz do que prometer resistir.', 'Existe outra forma de olhar para isso.', 'A promessa bíblica não é ausência de tentação, é existência de saída. Procurar a saída faz parte.', 'Deus... com a tentação, dará também um escape.', '1 Coríntios 10.13', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Identifique o gatilho (horário, lugar, estado emocional). Mude hoje uma coisa concreta no ambiente para dificultar o acesso.', 27),
('culpa', 'voce_consigo_mesmo', 'Culpa', 'Culpa que corrige é útil. Culpa que só te acusa é ruído com voz de moral.', 'O que está acontecendo no seu corpo?', 'A ruminação de culpa mantém estresse contínuo: sono ruim, tensão, irritabilidade.', 'O que está acontecendo dentro de você?', 'Culpa saudável fala sobre um ato: «eu fiz algo errado». Culpa tóxica fala sobre identidade: «eu sou errado». A primeira leva a reparo; a segunda, a paralisia.', 'Existe outra forma de olhar para isso.', 'O cristianismo separa arrependimento de autopunição. Arrependimento inclui mudança de rota e perdão recebido — não uma dívida eterna consigo mesmo.', 'Se confessarmos os nossos pecados, ele é fiel e justo para perdoá-los.', '1 João 1.9', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escreva o que você faria hoje se pudesse reparar 5% do que aconteceu. Faça esses 5%.', 28),
('vergonha', 'voce_consigo_mesmo', 'Vergonha', 'Vergonha é a mentira de que você precisa esconder para continuar sendo aceito.', 'O que está acontecendo no seu corpo?', 'Ela produz vontade física de sumir: cabeça baixa, ombros para dentro, evitação de contato.', 'O que está acontecendo dentro de você?', 'A vergonha vive de segredo. Ela perde força quando é contada a uma pessoa segura. Não a todo mundo: a uma pessoa.', 'Existe outra forma de olhar para isso.', 'A cena de Adão se escondendo é a primeira imagem de vergonha na Bíblia. Deus não responde com exposição pública: responde com uma pergunta e com roupa.', 'Onde você está?', 'Gênesis 3.9', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escolha uma pessoa segura e conte hoje uma coisa que você esconde. Uma pessoa, uma coisa.', 29),
('inseguranca', 'voce_consigo_mesmo', 'Insegurança', 'Você está esperando sentir confiança para agir. Funciona no sentido contrário.', 'O que está acontecendo no seu corpo?', 'Antes de situações de exposição, o corpo ativa alerta. A sensação é quase idêntica à de empolgação — o rótulo muda a experiência.', 'O que está acontecendo dentro de você?', 'Confiança é consequência de repetição com evidência. Sem ação, não há evidência; sem evidência, a mente mantém a dúvida.', 'Existe outra forma de olhar para isso.', 'A segurança bíblica não vem de autoimagem, e sim de pertencimento: você é conhecido antes de ser avaliado.', 'Antes de formá-lo no ventre eu o escolhi.', 'Jeremias 1.5', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Faça hoje algo pequeno que você faria se já fosse confiante. Anote depois o que realmente aconteceu.', 30),
('perfeccionismo', 'voce_consigo_mesmo', 'Perfeccionismo', 'Não é excelência. É medo bem vestido.', 'O que está acontecendo no seu corpo?', 'Padrões impossíveis mantêm tensão constante e são um caminho conhecido para o esgotamento.', 'O que está acontecendo dentro de você?', 'O perfeccionismo protege da crítica adiando a entrega. O custo é alto: menos feito, menos aprendizado, mais ansiedade.', 'Existe outra forma de olhar para isso.', 'A graça é exatamente o oposto do desempenho: você não é aceito porque acertou. Isso libera para tentar e errar.', 'Minha graça é suficiente para você, pois o meu poder se aperfeiçoa na fraqueza.', '2 Coríntios 12.9', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Entregue hoje algo em 80%. Publique, envie, mostre. Observe o que acontece de verdade.', 31),
('orgulho', 'voce_consigo_mesmo', 'Orgulho', 'O orgulho é a única coisa que te impede de receber justamente aquilo que você mais precisa.', 'O que está acontecendo no seu corpo?', 'Defesa constante é desgaste: manter uma imagem exige energia que poderia ser vivida.', 'O que está acontecendo dentro de você?', 'Orgulho e insegurança costumam morar juntos. Admitir erro parece perda de valor, então a mente escolhe estar certa em vez de estar bem.', 'Existe outra forma de olhar para isso.', 'A humildade bíblica não é se diminuir. É ver-se com precisão — inclusive nas partes boas.', 'Deus se opõe aos orgulhosos, mas concede graça aos humildes.', 'Tiago 4.6', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Peça desculpas hoje a alguém sem explicar, sem justificar e sem «mas».', 32),
('esgotamento', 'voce_consigo_mesmo', 'Esgotamento', 'Você está tentando descansar do jeito que cansa.', 'O que está acontecendo no seu corpo?', 'Exaustão prolongada afeta sono, humor, memória e imunidade. Rolagem no celular não repõe: é estímulo, não descanso.', 'O que está acontecendo dentro de você?', 'Esgotamento não é só volume de trabalho. É desequilíbrio entre esforço, controle e reconhecimento. Sem mudar as condições, o descanso só adia.', 'Existe outra forma de olhar para isso.', 'O descanso está no centro da narrativa bíblica desde o começo. Não é recompensa por produtividade: é parte do desenho.', 'Venham a mim todos os que estão cansados e sobrecarregados, e eu darei descanso a vocês.', 'Mateus 11.28', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Bloqueie hoje 60 minutos sem tela e sem tarefa. Durma 30 minutos mais cedo. Diga um não esta semana.', 33),
('sensacao-de-fracasso', 'voce_consigo_mesmo', 'Sensação de fracasso', 'Você transformou um capítulo difícil em uma definição inteira sobre quem você é.', 'O que está acontecendo no seu corpo?', 'A sensação de derrota reduz iniciativa e energia. O corpo se retrai antes da próxima tentativa.', 'O que está acontecendo dentro de você?', 'A mente cria uma narrativa fechada: «eu falhei» vira «eu sou um fracasso». Descrever os fatos com precisão desfaz boa parte da história.', 'Existe outra forma de olhar para isso.', 'Pedro negou publicamente e depois foi restaurado publicamente. A Bíblia é cheia de gente cuja falha não foi o fim da história.', 'Pois ainda que o justo caia sete vezes, tornará a levantar-se.', 'Provérbios 24.16', 'Agora faça alguma coisa com aquilo que você acabou de aprender.', 'Escreva os fatos em três frases, sem adjetivos. Depois escreva o que você aprendeu e o que faria diferente amanhã.', 34);